"""Build the portable brand review, motion study and social preview layouts."""
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'site'
ASSETS = SITE / 'assets'
BRAND = ROOT / 'brand'
GH = 'https://github.com/haohongfei2001-png/Riftlet/tree/design/brand-passage-20261030/design/brand-world-20261030'
for name in ['lockup.svg','lockup-light.svg','app-icon-forest.svg','directions-board.svg','scale-check.png','mark-mono.svg','menu-bar.svg','wordmark.svg']:
    shutil.copy2(BRAND/name, ASSETS/name)
for size in [16,32,64,128,256,512,1024]:
    shutil.copy2(BRAND/f'app-icon-{size}.png',ASSETS/f'app-icon-{size}.png')
for name in ['direction-a.svg','direction-c.svg']:
    shutil.copy2(BRAND/name,ASSETS/name)
(SITE/'baseline').mkdir(exist_ok=True)
for p in (ROOT/'baseline').iterdir():
    if p.suffix in ['.html','.css','.js','.svg','.webmanifest']:
        shutil.copy2(p,SITE/'baseline'/p.name)

